/**
 * Atkinson Hyperlegible Next Regular and Bold (OFL, see OFL.txt) as base64, for the
 * link-preview images (components/seo/open-graph-card.tsx). Generated from the TTF files
 * in this folder. Embedded in the code because Cloudflare Workers have no file system
 * and Node.js fetch() cannot read file: URLs, so this is the one way that works on both
 * Vercel and Cloudflare. To regenerate after changing a font:
 * node -e "console.log(require('fs').readFileSync('src/assets/fonts/<file>.ttf').toString('base64'))"
 */

export const atkinsonRegularBase64 =
  "";

export const atkinsonBoldBase64 =
  "";
